window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-176384e82b07b428"]={"versions": [{"id": "FIG-176384e82b07b428", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- und Prozessdiagramm im Kontext der AUTOSAR Adaptive Platform Methodology. Das Diagramm modelliert den methodischen Arbeitsschritt „Design service oriented communication between Classic and Adaptive Platform“ als zentrale Aktivität einschließlich ihrer Eingangs- und Ausgangsartefakte sowie der geschachtelten Teilaktivitäten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist die Aktivität <code>Design service oriented communication between Classic and Adaptive Platform</code>.</p>\n<p class=\"fig-p\">Eingangsartefakte (Deliverables/ARXML-Dateien mit Stereotyp <code>«input»</code>):</p>\n<ul class=\"fig-list\"><li><code>Service Interface Description</code> (Kardinalität 1)\n</li><li><code>Client Server Interface Description</code> (Kardinalität 0..*)\n</li><li><code>Sender Receiver Interface Description</code> (Kardinalität 0..*)\n</li><li><code>Trigger Interface Description</code> (Kardinalität 0..*)\n</li></ul>\n<p class=\"fig-p\">Ausgangsartefakt (Deliverable mit Stereotyp <code>«output»</code>):</p>\n<ul class=\"fig-list\"><li><code>Service Interface Mapping for Service Oriented Communication</code> (Kardinalität 1..*)\n</li></ul>\n<p class=\"fig-p\">Geschachtelte Aktivitäten (Verbindung über Komposition/Aggregation mit Stereotyp <code>«nesting»</code>):</p>\n<ul class=\"fig-list\"><li><code>Map Method</code>\n</li><li><code>Map Event</code>\n</li><li><code>Map Field</code>\n</li><li><code>Map Fire and Forget</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Aktivität nimmt die Schnittstellenbeschreibungen der beteiligten Plattformen entgegen: verbindlich mindestens eine <code>Service Interface Description</code> der Adaptive Platform sowie optional mehrere Schnittstellendefinitionen der Classic Platform (<code>Client Server Interface Description</code>, <code>Sender Receiver Interface Description</code>, <code>Trigger Interface Description</code>). Im Rahmen der Aktivität werden vier spezifische Mapping-Teilaktivitäten ausgeführt (<code>Map Method</code>, <code>Map Event</code>, <code>Map Field</code>, <code>Map Fire and Forget</code>), um die Dienstprimitiven der Adaptive Platform auf die Kommunikationsmuster der Classic Platform abzubilden. Als Ergebnis wird mindestens ein Deliverable <code>Service Interface Mapping for Service Oriented Communication</code> erzeugt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für den methodischen Übergang und die Interoperabilität zwischen AUTOSAR Classic und Adaptive Platform. Werkzeuge und Entwicklungsprozesse müssen sicherstellen, dass die serviceorientierten Kommunikationsmuster über die entsprechenden Mappings vollständig spezifiziert werden. Die Eingänge aus dem Classic-Bereich sind bedarfsabhängig (0..*), während eine Service-Interface-Beschreibung der Adaptive Platform zwingend erforderlich ist. Das Ergebnis-Deliverable dokumentiert die plattformübergreifenden Zuordnungen formal.</p>"}, {"id": "FIG-bcd76967d5558fc6", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- und Prozessdiagramm im Kontext der AUTOSAR Adaptive Platform Methodology. Das Diagramm modelliert den methodischen Arbeitsschritt „Design service oriented communication between Classic and Adaptive Platform“ als zentrale Aktivität einschließlich ihrer Eingangs- und Ausgangsartefakte sowie der geschachtelten Teilaktivitäten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist die Aktivität <code>Design service oriented communication between Classic and Adaptive Platform</code>.</p>\n<p class=\"fig-p\">Akteur und Rolle:</p>\n<ul class=\"fig-list\"><li>Akteur <code>OEM</code> führt die Aktivität in der Rolle <code>+Service Interface Designer</code> aus (Assoziation <code>«performs»</code>).\n</li></ul>\n<p class=\"fig-p\">Eingangsartefakte (Deliverables mit Stereotyp <code>«input»</code>):</p>\n<ul class=\"fig-list\"><li><code>Service Interface Description</code> (Kardinalität 1..*)\n</li><li><code>Client Server Interface Description</code> (Kardinalität 0..*)\n</li><li><code>Sender Receiver Interface Description</code> (Kardinalität 0..*)\n</li><li><code>Trigger Interface Description</code> (Kardinalität 0..*)\n</li></ul>\n<p class=\"fig-p\">Ausgangsartefakt und Struktur:</p>\n<ul class=\"fig-list\"><li><code>Service Interface Mapping for Service Oriented Communication</code> (Dokument/ARXML-Element, Kantenstereotyp <code>«output»</code> mit Kardinalität 1..*)\n</li><li><code>Service Interface Mapping Set</code> (Deliverable-Container, der über <code>«nesting»</code> 1..* Instanzen von <code>Service Interface Mapping for Service Oriented Communication</code> kapselt)\n</li></ul>\n<p class=\"fig-p\">Geschachtelte Teilaktivitäten (über Kanten mit Stereotyp <code>«nesting»</code> und Kardinalität je 0..* angebunden):</p>\n<ul class=\"fig-list\"><li><code>Map Method</code>\n</li><li><code>Map Event</code>\n</li><li><code>Map Field</code>\n</li><li><code>Map Fire and Forget</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der durch den <code>OEM</code> gestellte <code>Service Interface Designer</code> führt den Entwurfsschritt aus. Als Eingabe dienen eine oder mehrere <code>Service Interface Description</code>s (1..<em>) sowie optional Schnittstellenbeschreibungen aus der Classic Platform (<code>Client Server Interface Description</code>, <code>Sender Receiver Interface Description</code>, <code>Trigger Interface Description</code>, jeweils 0..</em>). Innerhalb des Entwurfsschritts werden bedarfsweise (0..*) die Mapping-Aktivitäten <code>Map Method</code>, <code>Map Event</code>, <code>Map Field</code> und <code>Map Fire and Forget</code> durchgeführt. Die resultierenden Zuordnungsdefinitionen <code>Service Interface Mapping for Service Oriented Communication</code> werden in einem übergeordneten Deliverable <code>Service Interface Mapping Set</code> gebündelt und bereitgestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für den methodischen Übergang und die Interoperabilität zwischen AUTOSAR Classic und Adaptive Platform. Werkzeuge und Entwicklungsprozesse müssen sicherstellen, dass die serviceorientierten Kommunikationsmuster über die entsprechenden Mappings vollständig spezifiziert werden. Die Eingänge aus dem Classic-Bereich sind bedarfsabhängig (0..*), während eine Service-Interface-Beschreibung der Adaptive Platform zwingend erforderlich ist. Das Ergebnis-Deliverable dokumentiert die plattformübergreifenden Zuordnungen formal.</p>"}, {"id": "FIG-8fedffcad649b248", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- und Prozessdiagramm im Kontext der AUTOSAR Adaptive Platform Methodology. Das Diagramm modelliert den methodischen Arbeitsschritt „Design service oriented communication between Classic and Adaptive Platform“ als zentrale Aktivität einschließlich ihrer Eingangs- und Ausgangsartefakte sowie der geschachtelten Teilaktivitäten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist die Aktivität <code>Design service oriented communication between Classic and Adaptive Platform</code>.</p>\n<p class=\"fig-p\">Akteur und Rolle:</p>\n<ul class=\"fig-list\"><li>Akteur <code>OEM</code> führt die Aktivität in der Rolle <code>+Service Interface Designer</code> aus (Assoziation <code>«performs»</code>).\n</li></ul>\n<p class=\"fig-p\">Eingangsartefakte (Deliverables mit Stereotyp <code>«input»</code>):</p>\n<ul class=\"fig-list\"><li><code>Service Interface Description</code> (Kardinalität 1..*)\n</li><li><code>Client Server Interface Description</code> (Kardinalität 0..*)\n</li><li><code>Sender Receiver Interface Description</code> (Kardinalität 0..*)\n</li><li><code>Trigger Interface Description</code> (Kardinalität 0..*)\n</li></ul>\n<p class=\"fig-p\">Ausgangsartefakt und Struktur:</p>\n<ul class=\"fig-list\"><li><code>Service Interface Mapping for Service Oriented Communication</code> (Dokument/ARXML-Element, Kantenstereotyp <code>«output»</code> mit Kardinalität 1..*)\n</li><li><code>Service Interface Mapping Set</code> (Deliverable-Container, der über <code>«nesting»</code> 1..* Instanzen von <code>Service Interface Mapping for Service Oriented Communication</code> kapselt)\n</li></ul>\n<p class=\"fig-p\">Geschachtelte Teilaktivitäten (über Kanten mit Stereotyp <code>«nesting»</code> und Kardinalität je 0..* angebunden):</p>\n<ul class=\"fig-list\"><li><code>Map Method</code>\n</li><li><code>Map Event</code>\n</li><li><code>Map Field</code>\n</li><li><code>Map Fire and Forget</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der durch den <code>OEM</code> gestellte <code>Service Interface Designer</code> führt den Entwurfsschritt aus. Als Eingabe dienen eine oder mehrere <code>Service Interface Description</code>s (1..<em>) sowie optional Schnittstellenbeschreibungen aus der Classic Platform (<code>Client Server Interface Description</code>, <code>Sender Receiver Interface Description</code>, <code>Trigger Interface Description</code>, jeweils 0..</em>). Innerhalb des Entwurfsschritts werden bedarfsweise (0..*) die Mapping-Aktivitäten <code>Map Method</code>, <code>Map Event</code>, <code>Map Field</code> und <code>Map Fire and Forget</code> durchgeführt. Die resultierenden Zuordnungsdefinitionen <code>Service Interface Mapping for Service Oriented Communication</code> werden in einem übergeordneten Deliverable <code>Service Interface Mapping Set</code> gebündelt und bereitgestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für den methodischen Übergang und die Interoperabilität zwischen AUTOSAR Classic und Adaptive Platform. Werkzeuge und Entwicklungsprozesse müssen sicherstellen, dass die serviceorientierten Kommunikationsmuster über die entsprechenden Mappings vollständig spezifiziert werden. Die Eingänge aus dem Classic-Bereich sind bedarfsabhängig (0..*), während eine Service-Interface-Beschreibung der Adaptive Platform zwingend erforderlich ist. Das Ergebnis-Deliverable dokumentiert die plattformübergreifenden Zuordnungen formal.</p>"}], "trans": [{"from": "FIG-176384e82b07b428", "to": "FIG-bcd76967d5558fc6", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Rolle hinzugefügt: Akteur <code>OEM</code> mit Rolle <code>+Service Interface Designer</code> über Assoziation <code>«performs»</code> an die Aktivität angebunden.\n</li><li>Eingangsartefakt <code>Service Interface Description</code>: Kardinalität von <code>1</code> auf <code>1..*</code> geändert.\n</li><li>Ausgangsartefakt modifiziert und hierarchisch erweitert: Das Dokumenten-Artefakt <code>Service Interface Mapping for Service Oriented Communication</code> (Typ von ARXML-Deliverable zu Plain-File/Model-Element geändert) ist über <code>«nesting»</code> mit Multiplizität <code>1..*</code> im Deliverable-Artefakt <code>Service Interface Mapping Set</code> enthalten.\n</li><li>Sub-Aktivitäten <code>Map Method</code>, <code>Map Event</code>, <code>Map Field</code>, <code>Map Fire and Forget</code>: Kardinalitäten an den <code>«nesting»</code>-Kanten jeweils explizit mit <code>0..*</code> annotiert.\n</li><li>Kanten-Kardinalitäten an den Eingängen <code>Client Server Interface Description</code>, <code>Sender Receiver Interface Description</code> und <code>Trigger Interface Description</code>: Positionierung der Kardinalitätsangabe <code>0..*</code> vom Aktivitätsziel an die Quellartefakte verlegt.\n</li></ul>"}, {"from": "FIG-bcd76967d5558fc6", "to": "FIG-8fedffcad649b248", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
